## When To Choose tRPC vs REST vs GraphQL

```
tRPC     → Monorepo/Next.js, TypeScript throughout, internal API only
REST     → Public API, multiple language clients, simple CRUD
GraphQL  → Complex data graph, multiple clients with different needs,
            mobile + web with different query requirements
```

## Long-Running Operation Patterns

## Pattern 1: Async Job (Polling)

```typescript
// POST /exports → 202 + jobId
export async function POST(req: Request) {
  const jobId = crypto.randomUUID();
  await queue.add('export', { jobId, ...await req.json() });
  return Response.json({ jobId }, {
    status: 202,
    headers: { Location: `/api/jobs/${jobId}` },
  });
}

// GET /jobs/:id → status
export async function GET(_: Request, { params }: { params: { id: string } }) {
  const job = await queue.getJob(params.id);
  return Response.json({
    status: job.status,      // 'pending' | 'processing' | 'done' | 'failed'
    progress: job.progress,  // 0-100
    result: job.status === 'done' ? job.result : null,
  });
}
```

## Pattern 2: Server-Sent Events (Real-Time Progress)

```typescript
export async function GET(req: Request, { params }: { params: { id: string } }) {
  const stream = new TransformStream();
  const writer = stream.writable.getWriter();
  const encoder = new TextEncoder();

  const send = (event: string, data: unknown) =>
    writer.write(encoder.encode(`event: ${event}\ndata: ${JSON.stringify(data)}\n\n`));

  // Run job in background
  (async () => {
    await send('progress', { percent: 0 });
    const step1 = await processStep1();
    await send('progress', { percent: 33 });
    const step2 = await processStep2(step1);
    await send('progress', { percent: 66 });
    const result = await finalise(step2);
    await send('done', { url: result.url });
    await writer.close();
  })();

  return new Response(stream.readable, {
    headers: {
      'Content-Type': 'text/event-stream',
      'Cache-Control': 'no-cache',
      Connection: 'keep-alive',
    },
  });
}

// Client
const es = new EventSource(`/api/jobs/${jobId}`);
es.addEventListener('progress', e => setProgress(JSON.parse(e.data).percent));
es.addEventListener('done', e => { setResult(e.data); es.close(); });
```

